// one icon as inline SVG: 24 x 24 line art in its own colour (or col), size px square
function runeIcon(id,size,col){ const I=RUNE_ICONS[id]; if(!I) return ''; const s=size||18;
  return '<svg class="ri" viewBox="0 0 24 24" width="'+s+'" height="'+s+'" style="color:'+(col||I[0])+'" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+I[1]+'</svg>'; }
// the same icon as a CSS url (for masks and backgrounds), in col
function runeIconUrl(id,col){ const I=RUNE_ICONS[id]; if(!I) return 'none'; const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="'+(col||I[0])+'" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+I[1]+'</svg>';
  return 'url("data:image/svg+xml,'+encodeURIComponent(svg)+'")'; }
